$ErrorActionPreference = "Stop"
$root = "C:\YTeMo"
if (-not (Test-Path (Join-Path $root "backend\main.py"))) { throw "Khong tim thay C:\YTeMo\backend\main.py" }
Set-Location $root
$python = Join-Path $root "backend\.venv\Scripts\python.exe"
if (-not (Test-Path $python)) { $python = (Get-Command python -ErrorAction Stop).Source }
$payload = @'

'@
$tempScript = Join-Path $env:TEMP "stt17_implementation_$PID.py"
[System.IO.File]::WriteAllBytes($tempScript, [Convert]::FromBase64String(($payload -replace "\s", "")))
try {
    & $python $tempScript
    $code = $LASTEXITCODE
} finally {
    Remove-Item $tempScript -Force -ErrorAction SilentlyContinue
}
if ($code -ne 0) { throw "STT17 implementation stopped with exit code $code. Read C:\YTeMo\STT17_IMPLEMENTATION_REPORT.txt if it was created." }
